pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 difficulty, address sender) public {
        // Restrict to admissible domain: sender cannot be zero address, and must have enough ETH for TICKET_AMOUNT
        vm.assume(sender != address(0));
        vm.assume(sender != address(c));
        // Ensure pot is initially 0, give sender Ether
        vm.deal(sender, 10 ether);
        // Set block context
        vm.warp(timestamp);
        vm.roll(difficulty);
        // Play with correct msg.value
        vm.prank(sender);
        c.play{value: 10}();
        // Recompute random as in contract to know whether a win occurred
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, sender))) % 2;
        bool isWin = (random == 0);
        // After play, if it was a win, pot MUST be 0; if loss, pot MUST be the accumulated stake (10 if no previous wins reset it)
        // Reference invariant: (isWin => pot == 0) AND (!isWin => pot != 0)
        // Since we call once from a fresh state, pot must be 0 for a win; otherwise it's 10.
        if (isWin) {
            assertTrue(c.pot() == 0);
        } else {
            assertTrue(c.pot() == 10);
        }
    }
}

