pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 calls, uint256 seed) public {
        // Bound the number of calls to a reasonable range to avoid excessive gas consumption
        calls = bound(calls, 0, 20);
        // Seed to randomize the outcome of each play() call (via block.timestamp and block.difficulty)
        // We'll use a counter to make each call unique.
        for (uint256 i = 0; i < calls; i++) {
            // To satisfy require(msg.value == TICKET_AMOUNT) we need to send exactly 10 wei.
            // We use a unique caller address derived from the fuzzed seed and counter.
            address caller = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            // Ensure the caller is not the bank (to avoid self-transfer confusion, though not strictly required)
            vm.assume(caller != c.bank());
            // Ensure caller is not the zero address
            vm.assume(caller != address(0));
            vm.deal(caller, 100 ether);
            // We manipulate block.timestamp and block.difficulty randomly for each call to control the random outcome.
            // The original contract uses block.timestamp and block.difficulty in its randomness.
            // We set them to values derived from seed and i to let the fuzzer explore different outcomes.
            vm.warp(uint256(keccak256(abi.encode(seed, i, "timestamp"))));
            vm.prevrandao(uint256(keccak256(abi.encode(seed, i, "prevrandao")))); // block.difficulty is now prevrandao
            vm.prank(caller);
            // The play() function reverts if msg.value != 10, so we must send exactly 10.
            // It may revert due to insufficient pot for transfer, but that's fine, we catch it.
            try c.play{value: 10}() {
                // success
            } catch {
                // ignore revert
            }
        }
        // After the sequence, the invariant: if pot > 0, it must be a multiple of TICKET_AMOUNT (10).
        // The bug leaves pot = 1 after a win, which violates this.
        uint256 currentPot = c.pot();
        assertTrue(currentPot == 0 || currentPot % 10 == 0);
    }
}

