pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 count) public {
        // count = number of losing plays before the winning play
        // at least 0 losing plays; we want at least one total play, so allow count >= 0
        // restrict to avoid excessive looping
        vm.assume(count < 50);

        // Perform 'count' losing plays where random != 0
        // We simulate losing by setting block values such that keccak256(...) % 2 != 0
        // Since random depends on block.timestamp, block.difficulty, msg.sender,
        // we can brute-force find a losing setup by changing timestamp.
        // We'll just call play() and if it wins (pot becomes 0), we assume it's not testable under these conditions,
        // but to guarantee losing, we can use a different sender each time and set difficulty to ensure odd result.
        // Actually, we can't control keccak256, but we can just call play and if it wins accidentally, we accept the scenario may be invalid; the assertion still holds.
        // To keep it simple: we just call play() count times from different addresses.
        for (uint i = 0; i < count; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10);
            vm.prank(player);
            c.play{value: 10}();
        }

        // Now perform one more play. After it, if random == 0 (win), pot should be 0.
        // The buggy version will have pot = 1 instead (extra increment not wiped by transfer).
        address finalPlayer = address(0x1234);
        vm.deal(finalPlayer, 10);
        vm.prank(finalPlayer);
        c.play{value: 10}();

        // After the final play, pot must be 0 (reference invariant)
        // Buggy version: after a win, pot becomes 1 instead of 0 if count == 0 and the win occurs on the first play.
        // Actually, in the reference, for any play where winner drawn, pot becomes 0 regardless of prior pot.
        // In mutant, transfer is pot - FEE where pot = priorPot + msg.value + 1, so pot after transfer is 1.
        // So invariant: pot is always either 0 or a multiple of something? But general rule: after any sequence, pot == 0 if last play won.
        // Since we don't control randomness, we can't guarantee the last play wins. But we can assert: if pot != 0, then pot >= 10? Not true for mutant (pot could be 1).
        // Better invariant: After a win, pot is 0. Since we don't know if the last play won, we can't assert pot==0 unconditionally.
        // But we can check: if the last play did NOT win, pot should be >0? No.
        // We need a different invariant. Let's think.
        // In reference, pot is always divisible by 10? Yes, because each play adds exactly 10 (msg.value == 10) until a win resets to 0.
        // So pot % 10 == 0 always. Mutant: extra +1 breaks this, making pot % 10 != 0 after some plays.
        // So invariant: pot % 10 == 0.
        // That's true for reference always; false for mutant after any play.
        assertTrue(c.pot() % 10 == 0);
    }
}

