pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 nPlays) public {
        // 1. Keep the number of plays in an admissible range (at least 1, up to a bound that fits test gas)
        bound(nPlays, 1, 20);

        // 2. Drive c through n plays, each from a fresh pranked sender with exactly TICKET_AMOUNT (10 wei)
        uint totalEthIn = 0;
        uint totalBankOut = 0;
        uint totalPlayerOut = 0;
        vm.deal(address(this), 10 * nPlays);
        for (uint i = 0; i < nPlays; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10);
            vm.prank(player);
            uint beforeBank = c.bank().balance;
            uint beforePlayer = player.balance;
            c.play{value: 10}();
            totalEthIn += 10;
            uint afterBank = c.bank().balance;
            uint afterPlayer = player.balance;
            // A win (random == 0) sends FEE_AMOUNT to bank and the rest to player, resetting pot to 0.
            // A loss (random != 0) sends nothing, pot accumulates.
            // Track all ETH that left the contract to bank and player.
            totalBankOut += (afterBank - beforeBank);
            totalPlayerOut += (afterPlayer - beforePlayer);
        }

        // 3. Invariant: totalEthIn == totalBankOut + totalPlayerOut + c.pot()
        // The reference always holds because every received wei either stays in pot or is transferred out.
        // The mutant adds +1 to pot per play without increasing msg.value, so totalEthIn stays the same
        // while totalTransferredOut + pot becomes > totalEthIn, breaking the equality.
        assertEq(totalEthIn, totalBankOut + totalPlayerOut + c.pot(), "ETH accounting invariant broken");
    }
}

