contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 numPlays, uint256 seed) public {
        // bound numPlays to a reasonable range to control loop iterations
        numPlays = uint8(bound(numPlays, 1, 20));

        // we will simulate the internal random logic by controlling block values
        // to deterministically control wins/losses across the fuzzed calls.
        // Use the seed to vary the random outcomes.
        uint256 wins = 0;
        for (uint256 i = 0; i < numPlays; i++) {
            // need a new sender each call with enough balance
            address player = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            vm.assume(player != address(0) && player != address(this) && player != address(c));
            vm.deal(player, 10 ether);

            // manipulate block.timestamp and block.difficulty so that the keccak256
            // produces a known outcome (we control whether random is 0 or 1).
            // We'll use the fuzzed seed to decide the random outcome for this play.
            bool win = ((uint256(keccak256(abi.encode(seed, i, "win"))) % 2) == 0);
            // we set block parameters to achieve this deterministic internal random
            // we can't directly set the keccak256 result, but we can loop the block.*
            // Actually, we can just trust the fuzzer to find combinations that trigger wins.
            // Instead, we set block.timestamp and block.difficulty to specific values
            // that we derive from seed so the fuzzer explores many hash outcomes.
            vm.warp(uint256(keccak256(abi.encode(seed, i, "time"))));
            vm.roll(uint256(keccak256(abi.encode(seed, i, "roll"))));
            // The difficulty is not directly settable via vm.difficulty (deprecated),
            // but block.difficulty is available in 0.8.0. We'll just let the fuzzer vary
            // the seed & numPlays, which indirectly varies block.timestamp & sender.
            // We must also make the msg.sender the player we created.
            vm.prank(player);
            c.play{value: 10}();

            // after the call, check if this was a win by observing pot being 0 or not
            // If pot is 0, a win occurred (random==0). Count it.
            if (c.pot() == 0) {
                wins++;
            }
        }

        // After all plays, if at least one win occurred, the final pot in P should be 0 every time a win resets it.
        // But the invariant we can assert: the pot is either 0 or 10*k (k losses), never something else.
        // In the buggy version, after a win the pot becomes FEE_AMOUNT (1) instead of 0.
        // So the general rule: pot must always be a multiple of TICKET_AMOUNT (10).
        // wins cause pot=0 (multiple of 10). Bug leaves pot=1 after first win, not a multiple of 10.
        assertTrue(c.pot() % 10 == 0);
    }
}

