pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n, uint256 seed) public {
        // restrict number of calls to a reasonable range to keep the invariant tractable
        vm.assume(n > 0 && n <= 5);

        // We need to drive sequences of `play()` calls. Since `play()` depends on
        // block.timestamp and block.difficulty and msg.sender for randomness, we
        // vary `msg.sender` and block properties across calls via fuzzed seed.
        // We will compute random results ourselves to track expected pot.
        // The reference invariant: at all times, address(c).balance == pot + 1 * (totalWins)
        // because each win transfers 1 to the bank. In P, pot is reset to 0 on a win,
        // so pot = 0 after every win and pot = address(c).balance - totalWins*FEE_AMOUNT.
        // The bug M fails to reset pot to 0, leaving pot = pot - FEE_AMOUNT, so
        // pot > address(c).balance - totalWins*FEE_AMOUNT after any win.

        // We'll generate a sequence of `n` calls, each receiving 10 wei.
        // Use vm.prank with different addresses (derived from seed+i) to vary msg.sender.
        uint256 totalWins = 0;
        uint256 expectedPot = 0; // P's pot at each step, but we will assert final relation
        for (uint8 i = 0; i < n; i++) {
            address caller = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            vm.deal(caller, 10);
            vm.prank(caller);
            // We must simulate block properties. Use vm.warp and vm.roll to vary them.
            vm.warp(uint256(keccak256(abi.encode(seed, i, 1))));
            vm.roll(uint256(keccak256(abi.encode(seed, i, 2))));
            c.play{value: 10}();

            // Determine if this call was a win (random == 0). Compute off-chain same as C.
            uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, caller))) % 2;
            if (random == 0) {
                totalWins++;
            }
        }

        // After all calls, reference P satisfies: address(c).balance == c.pot() + 1 * totalWins
        // Bug M violates this because pot is not reset but only decreased by FEE_AMOUNT,
        // so pot will be greater than address(c).balance - totalWins.
        // Therefore we assert the reference invariant: pot == address(c).balance - totalWins * 1
        // (equivalent to address(c).balance == pot + totalWins).
        assertTrue(c.pot() == address(c).balance - totalWins * 1 wei);
    }
}

